<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>WastedToken Mint</title>
<style>
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#0a0a0c;color:#eee}
header{padding:2.5rem 1rem;text-align:center}
header h1{margin:0;font-size:2.4rem;letter-spacing:.04em}
header p{margin:.5rem 0 0;color:#aaa}
#hero{display:flex;justify-content:center;padding:2rem;background:#0f0f14}
#coin-hero{width:800px;height:600px;background:#111;border-radius:16px;box-shadow:0 0 60px rgba(0,0,0,.6)}
#about{max-width:800px;margin:3rem auto;padding:0 2rem;line-height:1.7}
#about h2{font-size:1.8rem;margin-bottom:.8rem}
#collection{max-width:1000px;margin:3rem auto;padding:0 2rem}
.collection-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:2rem}
.edition{background:#15151c;border:1px solid #222;border-radius:14px;padding:1rem;text-align:center}
.edition-canvas{width:100%;height:auto;background:#0a0a0c;border-radius:10px;display:block}
.edition-info h3{margin:.6rem 0 .2rem}
.status{font-size:.85rem;color:#aaa}
.buy{margin-top:.8rem;padding:.6rem 1.2rem;background:#e0a020;border:none;border-radius:8px;cursor:pointer;font-weight:700;color:#111}
.edition[data-state="sold-out"]{opacity:.75}
.edition[data-state="coming-soon"]{opacity:.85}
footer{padding:2rem;text-align:center;color:#666;font-size:.85rem}
</style>
</head>
<body>
<header>
<h1>WASTED TOKEN MINT</h1>
<p>Collectible physical challenge coins. Minted. Weighted. Real.</p>
</header>
<main>
<section id="hero">
<canvas id="coin-hero" width="800" height="600"></canvas>
</section>
<section id="about">
<h2>About the Mint</h2>
<p>WastedToken Mint produces limited-run challenge coins for collectors, crews and the chronically online. Each piece is struck from a single blank, hand-finished and serialized. The front bears the WastedToken emblem in raised relief; the reverse declares the denomination in tokens. No two seasons repeat. If you see it, you can hold it. If it’s gone, it’s gone.</p>
</section>
<section id="collection">
<div class="collection-grid">
<div class="edition" data-edition="bronze" data-state="available">
<canvas class="edition-canvas" width="200" height="200"></canvas>
<div class="edition-info"><h3>Bronze</h3><span class="status">Available</span></div>
<button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="silver" data-state="available">
<canvas class="edition-canvas" width="200" height="200"></canvas>
<div class="edition-info"><h3>Silver</h3><span class="status">Available</span></div>
<button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="gold" data-state="sold-out">
<canvas class="edition-canvas" width="200" height="200"></canvas>
<div class="edition-info"><h3>Gold</h3><span class="status">SOLD OUT</span></div>
</div>
<div class="edition" data-edition="black" data-state="coming-soon">
<canvas class="edition-canvas" width="200" height="200"></canvas>
<div class="edition-info"><h3>Black (obsidian)</h3><span class="status">MINTING NEXT SEASON - WINTER</span></div>
</div>
</div>
</section>
</main>
<footer>© WastedToken Mint — For collectors and the troll kingdom</footer>
<script>
(() => {
function mat4Perspective(out,fovy,aspect,near,far){
  const f=1/Math.tan(fovy*0.5); const nf=1/(near-far);
  out[0]=f/aspect;out[1]=0;out[2]=0;out[3]=0;
  out[4]=0;out[5]=f;out[6]=0;out[7]=0;
  out[8]=0;out[9]=0;out[10]=(far+near)*nf;out[11]=-1;
  out[12]=0;out[13]=0;out[14]=2*far*near*nf;out[15]=0;
}
function compileShader(gl,type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s));return s;}
function createProgram(gl,vs,fs){const p=gl.createProgram();gl.attachShader(p,compileShader(gl,gl.VERTEX_SHADER,vs));gl.attachShader(p,compileShader(gl,gl.FRAGMENT_SHADER,fs));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(p));return p;}

const vsSource=`
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aUv;
attribute float aFaceId;
uniform mat4 uProjectionMatrix;
uniform float uRotX;
uniform float uRotY;
varying vec3 vNormal;
varying vec2 vUv;
varying float vFaceId;
vec3 rotateX(vec3 v,float a){float c=cos(a);float s=sin(a);return vec3(v.x, v.y*c - v.z*s, v.y*s + v.z*c);}
vec3 rotateY(vec3 v,float a){float c=cos(a);float s=sin(a);return vec3(v.x*c + v.z*s, v.y, -v.x*s + v.z*c);}
void main(){
  vec3 pos=aPosition; pos=rotateX(pos,uRotX); pos=rotateY(pos,uRotY); pos.z-=4.0;
  vec3 n=aNormal; n=rotateX(n,uRotX); n=rotateY(n,uRotY);
  vNormal=n; vUv=aUv; vFaceId=aFaceId;
  gl_Position=uProjectionMatrix*vec4(pos,1.0);
}`;
const fsSource=`
precision mediump float;
varying vec3 vNormal; varying vec2 vUv; varying float vFaceId;
uniform vec3 uLightDir; uniform sampler2D uFrontTex; uniform sampler2D uBackTex; uniform vec3 uBaseColor;
void main(){
  vec3 N=normalize(vNormal); vec3 L=normalize(uLightDir);
  float diff=max(dot(N,L),0.0);
  vec3 R=reflect(-L,N); vec3 V=vec3(0.0,0.0,1.0);
  float spec=pow(max(dot(normalize(R),V),0.0),64.0);
  vec3 tex;
  if(vFaceId<0.5){tex=texture2D(uFrontTex,vUv).rgb;}
  else if(vFaceId<1.5){tex=texture2D(uBackTex,vUv).rgb;}
  else {tex=vec3(0.7);}
  vec3 base=uBaseColor*tex;
  vec3 lit=base*(0.2+0.8*diff)+vec3(1.0)*spec*0.6;
  gl_FragColor=vec4(lit,1.0);
}`;

function buildCoinGeometry(numSegments=64,numRidges=80,radius=1.0,thickness=0.15){
  const positions=[],normals=[],uvs=[],faceIds=[],indices=[];
  const frontCenter=positions.length/3;
  positions.push(0,0,thickness/2); normals.push(0,0,1); uvs.push(0.5,0.5); faceIds.push(0);
  const frontRingStart=positions.length/3;
  for(let i=0;i<numSegments;i++){const a=2*Math.PI*i/numSegments;const x=radius*Math.cos(a);const y=radius*Math.sin(a);
    positions.push(x,y,thickness/2); normals.push(0,0,1); uvs.push(0.5+0.5*Math.cos(a),0.5+0.5*Math.sin(a)); faceIds.push(0);}
  for(let i=0;i<numSegments;i++){const i1=frontRingStart+i; const i2=frontRingStart+((i+1)%numSegments); indices.push(frontCenter,i1,i2);}
  const backCenter=positions.length/3;
  positions.push(0,0,-thickness/2); normals.push(0,0,-1); uvs.push(0.5,0.5); faceIds.push(1);
  const backRingStart=positions.length/3;
  for(let i=0;i<numSegments;i++){const a=2*Math.PI*i/numSegments;const x=radius*Math.cos(a);const y=radius*Math.sin(a);
    positions.push(x,y,-thickness/2); normals.push(0,0,-1); uvs.push(0.5+0.5*Math.cos(a),0.5+0.5*Math.sin(a)); faceIds.push(1);}
  for(let i=0;i<numSegments;i++){const i1=backRingStart+i; const i2=backRingStart+((i+1)%numSegments); indices.push(backCenter,i2,i1);}
  const sideStart=positions.length/3;
  for(let i=0;i<numSegments;i++){const a=2*Math.PI*i/numSegments;const ridge=0.02*Math.sin(a*numRidges);const r=radius+ridge;const x=r*Math.cos(a);const y=r*Math.sin(a);
    positions.push(x,y,thickness/2); normals.push(Math.cos(a),Math.sin(a),0); uvs.push(i/numSegments,1.0); faceIds.push(2);
    positions.push(x,y,-thickness/2); normals.push(Math.cos(a),Math.sin(a),0); uvs.push(i/numSegments,0.0); faceIds.push(2);}
  for(let i=0;i<numSegments;i++){const n=(i+1)%numSegments;const aTop=sideStart+i*2;const aBot=sideStart+i*2+1;const bTop=sideStart+n*2;const bBot=sideStart+n*2+1;
    indices.push(aTop,aBot,bTop); indices.push(aBot,bBot,bTop);}
  return {positions,normals,uvs,faceIds,indices};
}
function makeTexture(gl,draw){
  const size=256; const c=document.createElement('canvas'); c.width=c.height=size; const ctx=c.getContext('2d'); draw(ctx,size);
  const tex=gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D,tex); gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,c);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
  return tex;
}
class CoinRenderer{
  constructor(canvas,opts={}){
    this.canvas=canvas; this.gl=canvas.getContext('webgl'); if(!this.gl) throw new Error('WebGL not supported');
    this.baseColor=opts.baseColor||[1,1,1];
    this.geometry=buildCoinGeometry();
    this.program=createProgram(this.gl,vsSource,fsSource);
    this.posBuf=this.gl.createBuffer(); this.gl.bindBuffer(this.gl.ARRAY_BUFFER,this.posBuf); this.gl.bufferData(this.gl.ARRAY_BUFFER,new Float32Array(this.geometry.positions),this.gl.STATIC_DRAW);
    this.normBuf=this.gl.createBuffer(); this.gl.bindBuffer(this.gl.ARRAY_BUFFER,this.normBuf); this.gl.bufferData(this.gl.ARRAY_BUFFER,new Float32Array(this.geometry.normals),this.gl.STATIC_DRAW);
    this.uvBuf=this.gl.createBuffer(); this.gl.bindBuffer(this.gl.ARRAY_BUFFER,this.uvBuf); this.gl.bufferData(this.gl.ARRAY_BUFFER,new Float32Array(this.geometry.uvs),this.gl.STATIC_DRAW);
    this.faceBuf=this.gl.createBuffer(); this.gl.bindBuffer(this.gl.ARRAY_BUFFER,this.faceBuf); this.gl.bufferData(this.gl.ARRAY_BUFFER,new Float32Array(this.geometry.faceIds),this.gl.STATIC_DRAW);
    this.indexBuf=this.gl.createBuffer(); this.gl.bindBuffer(this.gl.ELEMENT_ARRAY_BUFFER,this.indexBuf); this.gl.bufferData(this.gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(this.geometry.indices),this.gl.STATIC_DRAW);
    this.frontTex=makeTexture(this.gl,(ctx,s)=>{ctx.fillStyle='#d0d0d0';ctx.fillRect(0,0,s,s);ctx.fillStyle='#e8e8e8';ctx.beginPath();ctx.arc(s/2,s/2,s/2-12,0,2*Math.PI);ctx.fill();ctx.strokeStyle='#888';ctx.lineWidth=6;ctx.beginPath();ctx.arc(s/2,s/2,s/2-30,0,2*Math.PI);ctx.stroke();ctx.fillStyle='#222';ctx.font='bold 28px sans-serif';ctx.textAlign='center';ctx.fillText('WASTED',s/2,s/2-10);ctx.fillText('TOKEN',s/2,s/2+20);ctx.font='18px sans-serif';ctx.fillText('MINT',s/2,s/2+50);});
    this.backTex=makeTexture(this.gl,(ctx,s)=>{ctx.fillStyle='#d0d0d0';ctx.fillRect(0,0,s,s);ctx.fillStyle='#e8e8e8';ctx.beginPath();ctx.arc(s/2,s/2,s/2-12,0,2*Math.PI);ctx.fill();ctx.fillStyle='#222';ctx.font='bold 32px sans-serif';ctx.textAlign='center';ctx.fillText('10,000',s/2,s/2-10);ctx.font='24px sans-serif';ctx.fillText('TOKENS',s/2,s/2+24);});
    this.uProjection=this.gl.getUniformLocation(this.program,'uProjectionMatrix');
    this.uRotX=this.gl.getUniformLocation(this.program,'uRotX');
    this.uRotY=this.gl.getUniformLocation(this.program,'uRotY');
    this.uLightDir=this.gl.getUniformLocation(this.program,'uLightDir');
    this.uBaseColor=this.gl.getUniformLocation(this.program,'uBaseColor');
    this.uFrontTex=this.gl.getUniformLocation(this.program,'uFrontTex');
    this.uBackTex=this.gl.getUniformLocation(this.program,'uBackTex');
    this.aPosition=this.gl.getAttribLocation(this.program,'aPosition');
    this.aNormal=this.gl.getAttribLocation(this.program,'aNormal');
    this.aUv=this.gl.getAttribLocation(this.program,'aUv');
    this.aFaceId=this.gl.getAttribLocation(this.program,'aFaceId');
  }
  render(t){
    const gl=this.gl, c=this.canvas;
    gl.viewport(0,0,c.width,c.height);
    gl.clearColor(0.06,0.06,0.08,1); gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT); gl.enable(gl.DEPTH_TEST);
    const proj=new Float32Array(16); mat4Perspective(proj,Math.PI/4,c.width/canvas.height,0.1,100);
    gl.useProgram(this.program);
    gl.uniformMatrix4fv(this.uProjection,false,proj);
    const rotX=Math.sin(t*Math.PI*2)*Math.PI*0.5;
    const rotY=t*Math.PI*2*1.5;
    gl.uniform1f(this.uRotX,rotX); gl.uniform1f(this.uRotY,rotY);
    gl.uniform3fv(this.uLightDir,[0.5,0.8,1.0]); gl.uniform3fv(this.uBaseColor,this.baseColor);
    gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D,this.frontTex); gl.uniform1i(this.uFrontTex,0);
    gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D,this.backTex); gl.uniform1i(this.uBackTex,1);
    gl.bindBuffer(gl.ARRAY_BUFFER,this.posBuf); gl.enableVertexAttribArray(this.aPosition); gl.vertexAttribPointer(this.aPosition,3,gl.FLOAT,false,0,0);
    gl.bindBuffer(gl.ARRAY_BUFFER,this.normBuf); gl.enableVertexAttribArray(this.aNormal); gl.vertexAttribPointer(this.aNormal,3,gl.FLOAT,false,0,0);
    gl.bindBuffer(gl.ARRAY_BUFFER,this.uvBuf); gl.enableVertexAttribArray(this.aUv); gl.vertexAttribPointer(this.aUv,2,gl.FLOAT,false,0,0);
    gl.bindBuffer(gl.ARRAY_BUFFER,this.faceBuf); gl.enableVertexAttribArray(this.aFaceId); gl.vertexAttribPointer(this.aFaceId,1,gl.FLOAT,false,0,0);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,this.indexBuf);
    gl.drawElements(gl.TRIANGLES,this.geometry.indices.length,gl.UNSIGNED_SHORT,0);
  }
}
const heroCanvas=document.getElementById('coin-hero');
const heroRenderer=new CoinRenderer(heroCanvas,{baseColor:[0.92,0.92,0.96]});
document.querySelectorAll('.edition').forEach(el=>{
  const canvas=el.querySelector('.edition-canvas');
  const edition=el.dataset.edition;
  let base;
  if(edition==='bronze') base=[0.8,0.5,0.25];
  else if(edition==='silver') base=[0.85,0.85,0.9];
  else if(edition==='gold') base=[1.0,0.85,0.2];
  else base=[0.12,0.12,0.15];
  const r=new CoinRenderer(canvas,{baseColor:base});
  r.render(0.3);
});
let animId=null, start=performance.now(), duration=8000;
function loop(now){const t=((now-start)%duration)/duration; heroRenderer.render(t); animId=requestAnimationFrame(loop);}
loop(performance.now());
window.demo={canvas:heroCanvas,setTime(t){const tt=((t%1)+1)%1; heroRenderer.render(tt);},pause(){if(animId){cancelAnimationFrame(animId);animId=null;}}};
})();
</script>
</body>
</html>
